public static class Final1113ContactImports {public static string Run(){if(Application.isPlaying)throw new Exception("Edit required");AssetDatabase.ImportAsset("Assets/Resources/MeshyNative/WorkContactProfiles.json",ImportAssetOptions.ForceUpdate);var paths=new[]{"Environment1110/Models/Rock/Rock","Environment1110/Models/Oak/Oak","Environment1110/Models/Pine/Pine","Environment1110/Models/IronDeposit/IronDeposit","Environment1110/Models/CopperDeposit/CopperDeposit","ResourceModels/CC_RockOutcrop","ResourceModels/CC_OreOutcrop","ResourceModels/CC_TreeTall","ResourceModels/CC_TreeBroadleaf","ResourceModels/Mineral_Sand","ResourceModels/Mineral_Clay"};string report="";foreach(var p in paths){string path="Assets/Resources/"+p+".fbx";var importer=AssetImporter.GetAtPath(path) as ModelImporter;if(!importer)throw new Exception(path);if(!importer.isReadable){importer.isReadable=true;importer.SaveAndReimport();}report+=path+" CPU surface access enabled\n";}File.WriteAllText("work/final-motion-1113/contact-imports.txt",report);return report;}}
